INSERT INTO `candidate_email_logs` (`id`, `organization_id`, `candidate_id`, `recipient_email`, `subject`, `body_content`, `email_type`, `status`, `sent_by`, `created_at`) VALUES
(1, 5, 389, 'ndertech@gmail.com', 'Renewal Notice: Your Ndertech CBT Pro Plan expires in 2 days!', '\n                <!DOCTYPE html>\n                <html>\n                <head>\n                    <meta charset=\'utf-8\'>\n                    <title>Plan Renewal Notice</title>\n                </head>\n                <body style=\'background-color: #f1f5f9; font-family: Arial, sans-serif; margin: 0; padding: 30px;\'>\n                    <div style=\'max-width: 600px; margin: 0 auto; background: #ffffff; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 20px rgba(0,0,0,0.08); border: 1px solid #e2e8f0;\'>\n                        <!-- Header -->\n                        <div style=\'background: linear-gradient(135deg, #f59e0b, #d97706); color: #ffffff; padding: 30px; text-align: center;\'>\n                            <h1 style=\'margin: 0 0 8px 0; font-size: 22px;\'>Subscription Renewal Notice ⚠️</h1>\n                            <p style=\'margin: 0; font-size: 14px; opacity: 0.95;\'>Your CBT Pro access plan requires renewal soon</p>\n                        </div>\n\n                        <!-- Body Content -->\n                        <div style=\'padding: 30px;\'>\n                            <p style=\'font-size: 16px; color: #1e293b; margin-top: 0;\'>Hello <strong>Avela</strong>,</p>\n                            <p style=\'color: #475569; font-size: 14px; line-height: 1.6;\'>Your Ndertech CBT Pro subscription plan for registration number <strong style=\'color: #0d6efd; font-family: monospace;\'>JAMB2026172925</strong> is expiring on <strong>2026-11-02 23:39:43</strong>.</p>\n\n                            <!-- Expiry Countdown Box -->\n                            <div style=\'background: #fffbeb; border: 1px solid #fde68a; border-radius: 12px; padding: 20px; margin: 25px 0; text-align: center;\'>\n                                <span style=\'font-size: 13px; color: #b45309; display: block; font-weight: bold; margin-bottom: 4px;\'>TIME REMAINING</span>\n                                <span style=\'font-size: 26px; font-weight: bold; color: #92400e;\'>2 Days Left</span>\n                            </div>\n\n                            <p style=\'color: #475569; font-size: 14px; line-height: 1.5;\'>Please log in to your candidate portal and renew your plan promptly to maintain uninterrupted access to your CBT examinations and practice tests.</p>\n\n                            <!-- Call to Action Button -->\n                            <div style=\'text-align: center; margin: 30px 0 10px 0;\'>\n                                <a href=\'https://cbt-for-all.digitalderivativeservices.com/candidate/\' style=\'background: #0d6efd; color: #ffffff; padding: 12px 30px; border-radius: 30px; font-weight: bold; text-decoration: none; font-size: 14px; display: inline-block; box-shadow: 0 4px 12px rgba(13,110,253,0.3);\'>Log In to Candidate Portal 🚀</a>\n                            </div>\n                        </div>\n\n                        <!-- Footer -->\n                        <div style=\'background: #f8fafc; padding: 20px; text-align: center; border-top: 1px solid #e2e8f0; font-size: 12px; color: #94a3b8;\'>\n                            <p style=\'margin: 0;\'>Best regards,<br><strong>NderTech Universal Services</strong></p>\n                        </div>\n                    </div>\n                </body>\n                </html>', 'expiry_notice', 'sent', 'system', '2026-11-01 13:09:30'),
(2, 5, 389, 'ndertech@gmail.com', 'RESEND: Renewal Notice: Your Ndertech CBT Pro Plan expires in 2 days!', '\n                <!DOCTYPE html>\n                <html>\n                <head>\n                    <meta charset=\'utf-8\'>\n                    <title>Plan Renewal Notice</title>\n                </head>\n                <body style=\'background-color: #f1f5f9; font-family: Arial, sans-serif; margin: 0; padding: 30px;\'>\n                    <div style=\'max-width: 600px; margin: 0 auto; background: #ffffff; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 20px rgba(0,0,0,0.08); border: 1px solid #e2e8f0;\'>\n                        <!-- Header -->\n                        <div style=\'background: linear-gradient(135deg, #f59e0b, #d97706); color: #ffffff; padding: 30px; text-align: center;\'>\n                            <h1 style=\'margin: 0 0 8px 0; font-size: 22px;\'>Subscription Renewal Notice ⚠️</h1>\n                            <p style=\'margin: 0; font-size: 14px; opacity: 0.95;\'>Your CBT Pro access plan requires renewal soon</p>\n                        </div>\n\n                        <!-- Body Content -->\n                        <div style=\'padding: 30px;\'>\n                            <p style=\'font-size: 16px; color: #1e293b; margin-top: 0;\'>Hello <strong>Avela</strong>,</p>\n                            <p style=\'color: #475569; font-size: 14px; line-height: 1.6;\'>Your Ndertech CBT Pro subscription plan for registration number <strong style=\'color: #0d6efd; font-family: monospace;\'>JAMB2026172925</strong> is expiring on <strong>2026-11-02 23:39:43</strong>.</p>\n\n                            <!-- Expiry Countdown Box -->\n                            <div style=\'background: #fffbeb; border: 1px solid #fde68a; border-radius: 12px; padding: 20px; margin: 25px 0; text-align: center;\'>\n                                <span style=\'font-size: 13px; color: #b45309; display: block; font-weight: bold; margin-bottom: 4px;\'>TIME REMAINING</span>\n                                <span style=\'font-size: 26px; font-weight: bold; color: #92400e;\'>2 Days Left</span>\n                            </div>\n\n                            <p style=\'color: #475569; font-size: 14px; line-height: 1.5;\'>Please log in to your candidate portal and renew your plan promptly to maintain uninterrupted access to your CBT examinations and practice tests.</p>\n\n                            <!-- Call to Action Button -->\n                            <div style=\'text-align: center; margin: 30px 0 10px 0;\'>\n                                <a href=\'https://cbt-for-all.digitalderivativeservices.com/candidate/\' style=\'background: #0d6efd; color: #ffffff; padding: 12px 30px; border-radius: 30px; font-weight: bold; text-decoration: none; font-size: 14px; display: inline-block; box-shadow: 0 4px 12px rgba(13,110,253,0.3);\'>Log In to Candidate Portal 🚀</a>\n                            </div>\n                        </div>\n\n                        <!-- Footer -->\n                        <div style=\'background: #f8fafc; padding: 20px; text-align: center; border-top: 1px solid #e2e8f0; font-size: 12px; color: #94a3b8;\'>\n                            <p style=\'margin: 0;\'>Best regards,<br><strong>NderTech Universal Services</strong></p>\n                        </div>\n                    </div>\n                </body>\n                </html>', 'expiry_notice', 'sent', 'system', '2026-11-01 13:38:29'),
(3, 5, 389, 'ndertech@gmail.com', 'Your Examination Result Scorecard - Biology Students 2027', '\n    <!DOCTYPE html>\n    <html>\n    <head>\n        <meta charset=\'utf-8\'>\n        <title>Assessment Result Report</title>\n    </head>\n    <body style=\'background-color: #f1f5f9; font-family: Arial, sans-serif; margin: 0; padding: 30px;\'>\n        <div style=\'max-width: 650px; margin: 0 auto; background: #ffffff; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 20px rgba(0,0,0,0.08); border: 1px solid #e2e8f0;\'>\n            <!-- Header -->\n            <div style=\'background: linear-gradient(135deg, #0d6efd, #3b82f6); color: #ffffff; padding: 30px; text-align: center;\'>\n                <h1 style=\'margin: 0 0 8px 0; font-size: 24px;\'>Ndertech Universal Services Pro</h1>\n                <p style=\'margin: 0; font-size: 14px; opacity: 0.9;\'>Official Assessment Scorecard & Result Report</p>\n            </div>\n\n            <!-- Body Content -->\n            <div style=\'padding: 30px;\'>\n                <p style=\'font-size: 16px; color: #1e293b; margin-top: 0;\'>Dear <strong>Avela Marcel</strong>,</p>\n                <p style=\'color: #475569; font-size: 14px; line-height: 1.5;\'>Your examination results for <strong>Biology Students 2027</strong> have been successfully processed and verified.</p>\n\n                <!-- Summary Box -->\n                <div style=\'background: #eff6ff; border: 1px solid #dbeafe; border-radius: 12px; padding: 20px; margin: 25px 0;\'>\n                    <table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\'>\n                        <tr>\n                            <td style=\'text-align: center; border-right: 1px solid #cbd5e1; padding-right: 15px;\'>\n                                <span style=\'font-size: 12px; color: #64748b; display: block; margin-bottom: 4px;\'>TOTAL SCORE</span>\n                                <span style=\'font-size: 22px; font-weight: bold; color: #0d6efd;\'>75 <span style=\'font-size: 14px; font-weight: normal; color: #64748b;\'>/ 231</span></span>\n                            </td>\n                            <td style=\'text-align: center; border-right: 1px solid #cbd5e1; padding: 0 15px;\'>\n                                <span style=\'font-size: 12px; color: #64748b; display: block; margin-bottom: 4px;\'>PERCENTAGE</span>\n                                <span style=\'font-size: 22px; font-weight: bold; color: #1e293b;\'>32.5%</span>\n                            </td>\n                            <td style=\'text-align: center; padding-left: 15px;\'>\n                                <span style=\'font-size: 12px; color: #64748b; display: block; margin-bottom: 4px;\'>OUTCOME</span>\n                                <span style=\'font-size: 14px; font-weight: bold; padding: 5px 12px; border-radius: 20px; background: #f8d7da; color: #842029; display: inline-block;\'>Failed Assessment</span>\n                            </td>\n                        </tr>\n                    </table>\n                </div>\n\n                <h3 style=\'color: #1e293b; font-size: 16px; border-bottom: 2px solid #e2e8f0; padding-bottom: 8px; margin-top: 30px;\'>Subject Performance Breakdown</h3>\n                \n                \n        <div style=\'background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 14px; margin-bottom: 12px;\'>\n            <div style=\'font-weight: bold; color: #0d6efd; font-size: 15px; margin-bottom: 6px;\'>Chemistry - 2027 <span style=\'color: #64748b; font-size: 12px; font-weight: normal;\'>(CHEM - 2027)</span></div>\n            <table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' style=\'font-size: 13px; color: #334155;\'>\n                <tr>\n                    <td><strong>Score:</strong> 25 / 66</td>\n                    <td><strong>Percentage:</strong> 37.88%</td>\n                </tr>\n                <tr>\n                    <td style=\'padding-top: 4px;\'><strong>Correct:</strong> <span style=\'color: #198754;\'>18</span> / 50</td>\n                    <td style=\'padding-top: 4px;\'><strong>Wrong/Unanswered:</strong> <span style=\'color: #dc3545;\'>32</span></td>\n                </tr>\n            </table>\n        </div>\n        <div style=\'background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 14px; margin-bottom: 12px;\'>\n            <div style=\'font-weight: bold; color: #0d6efd; font-size: 15px; margin-bottom: 6px;\'>English Language - 2027 <span style=\'color: #64748b; font-size: 12px; font-weight: normal;\'>(ENG - 2027)</span></div>\n            <table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' style=\'font-size: 13px; color: #334155;\'>\n                <tr>\n                    <td><strong>Score:</strong> 19 / 53.5</td>\n                    <td><strong>Percentage:</strong> 35.51%</td>\n                </tr>\n                <tr>\n                    <td style=\'padding-top: 4px;\'><strong>Correct:</strong> <span style=\'color: #198754;\'>17</span> / 50</td>\n                    <td style=\'padding-top: 4px;\'><strong>Wrong/Unanswered:</strong> <span style=\'color: #dc3545;\'>33</span></td>\n                </tr>\n            </table>\n        </div>\n        <div style=\'background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 14px; margin-bottom: 12px;\'>\n            <div style=\'font-weight: bold; color: #0d6efd; font-size: 15px; margin-bottom: 6px;\'>Mathematics - 2027 <span style=\'color: #64748b; font-size: 12px; font-weight: normal;\'>(MATHS - 2027)</span></div>\n            <table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' style=\'font-size: 13px; color: #334155;\'>\n                <tr>\n                    <td><strong>Score:</strong> 20 / 61.5</td>\n                    <td><strong>Percentage:</strong> 32.52%</td>\n                </tr>\n                <tr>\n                    <td style=\'padding-top: 4px;\'><strong>Correct:</strong> <span style=\'color: #198754;\'>16</span> / 50</td>\n                    <td style=\'padding-top: 4px;\'><strong>Wrong/Unanswered:</strong> <span style=\'color: #dc3545;\'>34</span></td>\n                </tr>\n            </table>\n        </div>\n        <div style=\'background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 14px; margin-bottom: 12px;\'>\n            <div style=\'font-weight: bold; color: #0d6efd; font-size: 15px; margin-bottom: 6px;\'>Physics - 2027 <span style=\'color: #64748b; font-size: 12px; font-weight: normal;\'>(PHY - 2027)</span></div>\n            <table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' style=\'font-size: 13px; color: #334155;\'>\n                <tr>\n                    <td><strong>Score:</strong> 11 / 50</td>\n                    <td><strong>Percentage:</strong> 22%</td>\n                </tr>\n                <tr>\n                    <td style=\'padding-top: 4px;\'><strong>Correct:</strong> <span style=\'color: #198754;\'>11</span> / 50</td>\n                    <td style=\'padding-top: 4px;\'><strong>Wrong/Unanswered:</strong> <span style=\'color: #dc3545;\'>39</span></td>\n                </tr>\n            </table>\n        </div>\n\n                <p style=\'color: #64748b; font-size: 13px; margin-top: 25px; line-height: 1.4;\'>An official PDF copy of your detailed scorecard has been securely attached to this email for your records.</p>\n            </div>\n\n            <!-- Footer -->\n            <div style=\'background: #f8fafc; padding: 20px; text-align: center; border-top: 1px solid #e2e8f0; font-size: 12px; color: #94a3b8;\'>\n                <p style=\'margin: 0;\'>Powered by Ndertech Universal Services Pro | Automated Evaluation System</p>\n            </div>\n        </div>\n    </body>\n    </html>', 'scorecard', 'sent', 'admin', '2026-11-01 13:43:27'),
(4, 5, 400, 'zahemen@ndertech.com', 'Candidate Profile & Statement of Account - JAMB2026393391', '\n        <div style=\'font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 25px; border: 1px solid #e2e8f0; border-radius: 12px; background: #ffffff;\'>\n            <h2 style=\'color: #0d6efd; margin-bottom: 5px;\'>Ndertech Universal Services Pro</h2>\n            <p style=\'color: #64748b; font-size: 14px;\'>Official Candidate Statement & Transaction Report</p>\n            <hr style=\'border: 0; border-top: 1px solid #e2e8f0; margin: 20px 0;\'>\n            \n            <h3 style=\'color: #334155; margin-bottom: 15px;\'>Candidate Profile Information</h3>\n            <p style=\'margin: 6px 0;\'><strong>Full Name:</strong> Zahemen Nder</p>\n            <p style=\'margin: 6px 0;\'><strong>Registration Number:</strong> JAMB2026393391</p>\n            <p style=\'margin: 6px 0;\'><strong>Username:</strong> @Zahemen1</p>\n            <p style=\'margin: 6px 0;\'><strong>Program:</strong> General Program</p>\n            <p style=\'margin: 6px 0;\'><strong>Email Address:</strong> zahemen@ndertech.com</p>\n            <p style=\'margin: 6px 0;\'><strong>Phone Number:</strong> 09068984586</p>\n            <p style=\'margin: 6px 0;\'><strong>Gender:</strong> Male</p>\n            <p style=\'margin: 6px 0;\'><strong>Wallet Balance:</strong> ₦0.00</p>\n            <p style=\'margin: 6px 0;\'><strong>Account Status:</strong> Active</p>\n            <p style=\'margin: 6px 0;\'><strong>Registration Date:</strong> 2026-10-14 12:08:49</p>\n            <p style=\'margin: 6px 0;\'><strong>Plan Expiry Date:</strong> 2026-12-02 10:00:00</p>\n            \n            <h3 style=\'color: #334155; margin-top: 25px; margin-bottom: 15px;\'>Financial Summary</h3>\n            <p style=\'margin: 6px 0;\'><strong>Total Successful Spend:</strong> ₦2,500.00</p>\n            \n            <p style=\'margin-top: 35px; font-size: 12px; color: #94a3b8; text-align: center;\'>This