(2545, 9, 31, NULL, 'AC.DAY 4', 'mcq', 'medium', 'The ultimate indicator of success of a safe motherhood programme is', NULL, NULL, 0.40, 0.00, 'Maternal mortality ratio reflects the effectiveness of interventions aimed at reducing maternal deaths.', NULL, NULL, 1, 'active', 7, NULL, '2026-10-10 14:34:05', '2026-10-10 14:34:05', NULL),
(2546, 9, 31, NULL, 'AC.DAY 5', 'mcq', 'medium', 'The best time to suction the airway of a convulsing patient is', NULL, NULL, 0.40, 0.00, 'Suctioning is generally performed after convulsive movements stop, when it can be done safely to clear secretions and maintain airway patency.', NULL, NULL, 1, 'active', 7, NULL, '2026-10-10 14:34:05', '2026-10-10 14:34:05', NULL),
