(5395, 9, 33, NULL, 'AF-DEV-153', 'mcq', 'medium', 'An integrated system of care that supports a patient with chronic illnesses through a comprehensive range of health services is referred to as', NULL, NULL, 0.40, 0.00, 'A continuum of care coordinates healthcare services over time and across different settings to meet a patient\'s ongoing health needs.', NULL, NULL, 1, 'active', 7, NULL, '2026-10-13 15:58:17', '2026-10-13 15:58:17', NULL),
(5396, 9, 33, NULL, 'AF-DEV-154', 'mcq', 'medium', 'A comprehensive summary of previous research on a topic, used to identify gaps and inform a new study, is the', NULL, NULL, 0.40, 0.00, 'A literature review summarizes and evaluates existing research, identifies knowledge gaps and provides a foundation for a new study.', NULL, NULL, 1, 'active', 7, NULL, '2026-10-13 15:58:17', '2026-10-13 15:58:17', NULL),
(5397, 9, 33, NULL, 'AF-DEV-155', 'mcq', 'medium', 'Trypsinogen is secreted by the', NULL, NULL, 0.40, 0.00, 'The pancreas secretes inactive trypsinogen, which is activated to trypsin in the small intestine.', NULL, NULL, 1, 'active', 7, NULL, '2026-10-13 15:58:17', '2026-10-13 15:58:17', NULL),
(5398, 9, 33, NULL, 'AF-DEV-156', 'mcq', 'medium', 'The scientific study of body structures visible to the naked eye is known as', NULL, NULL, 0.40, 0.00, 'Gross anatomy studies body structures that can be observed without a microscope.', NULL, NULL, 1, 'active', 7, NULL, '2026-10-13 15:58:17', '2026-10-13 15:58:17', NULL),
