(5400, 9, 33, NULL, 'AF-DEV-158', 'mcq', 'medium', 'Measures of dispersion are calculated by use of', NULL, NULL, 0.40, 0.00, 'Standard deviation is a measure of dispersion that indicates how widely data values are spread around the mean.', NULL, NULL, 1, 'active', 7, NULL, '2026-10-13 15:58:17', '2026-10-13 15:58:17', NULL),
(5401, 9, 33, NULL, 'AF-DEV-159', 'mcq', 'medium', 'A whole that is greater than the sum of its parts is called', NULL, NULL, 0.40, 0.00, 'Holism views a person or system as a whole whose properties and functioning cannot be fully understood by examining individual parts alone.', NULL, NULL, 1, 'active', 7, NULL, '2026-10-13 15:58:17', '2026-10-13 15:58:17', NULL),
